import { useTenant } from '@/app/providers/TenantProvider'
import { Building2, Users, FolderKanban, Cpu, CreditCard } from 'lucide-react'

export function TenantOverviewPage() {
  const { manifest } = useTenant()

  const stats = [
    { label: 'Status', value: 'Active', icon: <Building2 size={16} />, color: 'text-success' },
    { label: 'Users', value: '24', icon: <Users size={16} />, color: 'text-accent' },
    { label: 'Projects', value: '8', icon: <FolderKanban size={16} />, color: 'text-info' },
    { label: 'Enabled apps', value: manifest?.enabledApps.length ?? 0, icon: <Cpu size={16} />, color: 'text-warning' },
    { label: 'Credits', value: '1,200', icon: <CreditCard size={16} />, color: 'text-primary' },
  ]

  return (
    <div className="h-full overflow-y-auto p-6">
      <div className="max-w-4xl mx-auto">
        <h2 className="font-semibold mb-1">Tenant overview</h2>
        <p className="text-sm text-muted-foreground mb-6">{manifest?.name} · {manifest?.slug}</p>
        <div className="grid grid-cols-2 md:grid-cols-5 gap-4 mb-8">
          {stats.map((s) => (
            <div key={s.label} className="bg-surface rounded-xl border border-border p-4">
              <span className={s.color}>{s.icon}</span>
              <p className="text-xl font-bold mt-2">{s.value}</p>
              <p className="text-xs text-muted-foreground mt-0.5">{s.label}</p>
            </div>
          ))}
        </div>
        <div className="bg-surface rounded-xl border border-border p-6">
          <h3 className="font-medium mb-4">Enabled apps</h3>
          <div className="flex flex-wrap gap-2">
            {manifest?.enabledApps.map((app) => (
              <span key={app} className="px-2.5 py-1 bg-muted rounded-full text-xs capitalize">{app}</span>
            ))}
          </div>
        </div>
      </div>
    </div>
  )
}
